    font-family: var(--font-sans);
    box-sizing: border-box;
    padding: 12px 16px;
    overflow: hidden;
  }
  .avl-root * { box-sizing: border-box; }
  .avl-controls {
    display: flex; align-items: center; gap: 12px;
