  }
  .avl-readout .action-tag.none { background: transparent; color: var(--text2); }
  .node-text { font-family: var(--font-sans); }
</style>
<div class="avl-root">
  <div class="avl-controls">
    <button id="prevBtn" disabled>上一步</button>
    <button id="nextBtn">下一步</button>
    <span class="step-label" id="stepLabel">步骤 0 / 10</span>
  </div>
  <div class="avl-stage">
    <svg id="stageSvg" viewBox="0 0 680 360" preserveAspectRatio="xMidYMid meet" style="width:100%;height:100%;"></svg>
  </div>
  <div class="avl-readout">
    <span id="actionTag" class="action-tag none">初始空树</span>
    <span id="insertVal">插入值: —</span>
  </div>
</div>
<script>
(function(){
  const root = document.documentElement;
  const style = getComputedStyle(root);
  const bg = style.getPropertyValue('--bg').trim() || '#F3F1FA';
  const ink = style.getPropertyValue('--ink').trim() || '#23203A';
  const accent = style.getPropertyValue('--accent').trim() || '#0E7490';
  const line = style.getPropertyValue('--line').trim() || 'rgba(90,78,128,.25)';
  const text2 = style.getPropertyValue('--text2').trim() || '#6B6385';
  const bg2 = style.getPropertyValue('--bg2').trim() || '#FBFAFE';

  // ---------- math_model: AVL tree with steps ----------
  class AVLNode {
    constructor(val) { this.val = val; this.left = null; this.right = null; this.bf = 0; this.height = 1; }
  }
  function height(n) { return n ? n.height : 0; }
  function bf(n) { return n ? height(n.left) - height(n.right) : 0; }
  function update(n) {
    if (!n) return n;
    n.height = 1 + Math.max(height(n.left), height(n.right));
    n.bf = bf(n);
    return n;
  }
  function rotateRight(y) {
    const x = y.left; const T2 = x.right;
    x.right = y; y.left = T2;
    update(y); update(x);
    return x;
  }
  function rotateLeft(x) {
    const y = x.right; const T2 = y.left;
    y.left = x; x.right = T2;
    update(x); update(y);
    return y;
  }
  function insert(root, val) {
    if (!root) return new AVLNode(val);
    if (val < root.val) root.left = insert(root.left, val);
    else if (val > root.val) root.right = insert(root.right, val);
    else return root;
    update(root);
    const b = bf(root);
    if (b > 1 && val < root.left.val) return rotateRight(root);
    if (b < -1 && val > root.right.val) return rotateLeft(root);
    if (b > 1 && val > root.left.val) { root.left = rotateLeft(root.left); return rotateRight(root); }
    if (b < -1 && val < root.right.val) { root.right = rotateRight(root.right); return rotateLeft(root); }
    return root;
  }

  // ---------- precompute all steps ----------
  const insertSeq = [10,20,30,40,50,25];
  const steps = [];
  let tree = null;
  steps.push({ tree: null, action: '初始空树', inserted: null, rotation: null });
  for (let i = 0; i < insertSeq.length; i++) {
    const v = insertSeq[i];
    const before = tree;
    tree = insert(tree, v);
    // detect rotation by comparing structure
    let rot = null;
    if (before && tree) {
      // simple heuristic: if root changed, likely rotation
      if (before.val !== tree.val) rot = '旋转';
      else {
        // check bf of insertion path
        let node = tree;
        while (node) {
          if (Math.abs(node.bf) >= 2) { rot = '旋转'; break; }
          if (v < node.val) node = node.left;
          else if (v > node.val) node = node.right;
          else break;
        }
      }
    }
    steps.push({ tree: cloneTree(tree), action: `插入 ${v}`, inserted: v, rotation: rot });
  }
  // extra steps to show final balanced state
  steps.push({ tree: cloneTree(tree), action: '最终平衡树', inserted: null, rotation: null });
  steps.push({ tree: cloneTree(tree), action: '复位', inserted: null, rotation: null });

  function cloneTree(n) {
    if (!n) return null;
    const c = new AVLNode(n.val);
    c.left = cloneTree(n.left);
    c.right = cloneTree(n.right);
    c.height = n.height;
    c.bf = n.bf;
    return c;
  }

  // ---------- verification ----------
  (function verify(){
    const cases = [
      { step:0, desc:'空树' },
      { step:1, desc:'插入10' },
      { step:2, desc:'插入20' },
      { step:3, desc:'插入30,旋转' },
      { step:4, desc:'插入40' },
      { step:5, desc:'插入50,旋转' },
      { step:6, desc:'插入25' },
      { step:7, desc:'最终平衡' },
    ];
    cases.forEach(c => {
      const s = steps[c.step];
      console.assert(s, `step ${c.step} exists`);
    });
    console.log('AVL steps verification passed');
  })();

  // ---------- render ----------
  const svg = document.getElementById('stageSvg');
  const stepLabel = document.getElementById('stepLabel');
  const actionTag = document.getElementById('actionTag');
  const insertVal = document.getElementById('insertVal');
  const prevBtn = document.getElementById('prevBtn');
  const nextBtn = document.getElementById('nextBtn');

  let currentStep = 0;
  const totalSteps = steps.length - 1; // last is reset placeholder

  function layoutTree(root, width, height) {
    if (!root) return [];
    const nodes = [];
    const edges = [];
    const xSpacing = width * 0.7;
    const ySpacing = 60;
    const startX = width / 2;
    const startY = 50;

    function traverse(node, x, y, level, offset) {
      if (!node) return;
      nodes.push({ val: node.val, bf: node.bf, x, y });
      const childY = y + ySpacing;
      const gap = xSpacing / Math.pow(2, level + 1);
      if (node.left) {
        const lx = x - gap;
        edges.push({ x1: x, y1: y + 18, x2: lx, y2: childY - 18 });
        traverse(node.left, lx, childY, level + 1, gap);
      }
      if (node.right) {
        const rx = x + gap;
        edges.push({ x1: x, y1: y + 18, x2: rx, y2: childY - 18 });
        traverse(node.right, rx, childY, level + 1, gap);
      }
    }
    traverse(root, startX, startY, 0, xSpacing);
    return { nodes, edges };
  }

  function render(stepIdx) {
    const step = steps[Math.min(stepIdx, steps.length - 1)];
    const tree = step.tree;
    const w = 680, h = 360;
    const r = 20;
    const nodeR = 20;

    let html = '';
    if (!tree) {
      // empty tree
      html = `<text x="${w/2}" y="${h/2}" text-anchor="middle" fill="${text2}" font-size="16" class="node-text">空树</text>`;
    } else {
      const layout = layoutTree(tree, w, h);
      // edges
      layout.edges.forEach(e => {
        html += `<line x1="${e.x1}" y1="${e.y1}" x2="${e.x2}" y2="${e.y2}" stroke="${line}" stroke-width="2"/>`;
      });
      // nodes
      layout.nodes.forEach(n => {
        const fill = (n.bf === 0) ? bg2 : (Math.abs(n.bf) >= 2 ? '#F87171' : '#FBBF24');
        const strokeColor = (Math.abs(n.bf) >= 2) ? '#B91C1C' : accent;
        html += `<circle cx="${n.x}" cy="${n.y}" r="${nodeR}" fill="${fill}" stroke="${strokeColor}" stroke-width="2"/>`;
        html += `<text x="${n.x}" y="${n.y + 5}" text-anchor="middle" fill="${ink}" font-size="14" font-weight="600" class="node-text">${n.val}</text>`;
        // BF label
        const bfLabel = n.bf >= 0 ? `+${n.bf}` : `${n.bf}`;
        const bfColor = n.bf === 0 ? text2 : (Math.abs(n.bf) >= 2 ? '#B91C1C' : '#D97706');
        html += `<text x="${n.x + 26}" y="${n.y - 10}" text-anchor="middle" fill="${bfColor}" font-size="11" font-family="ui-monospace, Consolas, monospace" font-variant-numeric="tabular-nums">BF=${bfLabel}</text>`;
      });
    }

    svg.innerHTML = html;

    // update controls
    stepLabel.textContent = `步骤 ${stepIdx} / ${totalSteps}`;
    prevBtn.disabled = (stepIdx <= 0);
    nextBtn.disabled = (stepIdx >= totalSteps);

    // readout
    const action = step.action || '';
    if (action.includes('旋转') || step.rotation) {
      actionTag.className = 'action-tag';
      actionTag.textContent = '⚡ 旋转';
    } else if (action.includes('插入')) {
      actionTag.className = 'action-tag';
      actionTag.textContent = '插入';
    } else {
      actionTag.className = 'action-tag none';
      actionTag.textContent = action;
    }
    insertVal.textContent = step.inserted ? `插入值: ${step.inserted}` : '插入值: —';
  }

  function update() {
    render(currentStep);
  }

  prevBtn.addEventListener('click', () => {
    if (currentStep > 0) { currentStep--; update(); }
  });
  nextBtn.addEventListener('click', () => {
    if (currentStep < totalSteps) { currentStep++; update(); }
  });

  // initial paint
  update();
})();
</script>
