<div class="avl-root">
  <div class="avl-controls">
    <button id="prevBtn" disabled>上一步</button>
    <button id="nextBtn">下一步</button>
    <span class="step-label" id="stepLabel">步骤 0 / 10</span>
  </div>
  <div class="avl-stage">
    <svg id="stageSvg" viewBox="0 0 680 360" preserveAspectRatio="xMidYMid meet" style="width:100%;height:100%;"></svg>
  </div>
  <div class="avl-readout">
    <span id="actionTag" class="action-tag none">初始空树</span>
    <span id="insertVal">插入值: —</span>
  </div>
</div>
<script>
(function(){
  var root = document.documentElement;
  var style = getComputedStyle(root);
  var bg = style.getPropertyValue('--bg').trim() || '#F3F1FA';
  var ink = style.getPropertyValue('--ink').trim() || '#23203A';
  var accent = style.getPropertyValue('--accent').trim() || '#0E7490';
  var line = style.getPropertyValue('--line').trim() || 'rgba(90,78,128,.25)';
  var text2 = style.getPropertyValue('--text2').trim() || '#6B6385';
  var bg2 = style.getPropertyValue('--bg2').trim() || '#FBFAFE';

  function AVLNode(val) { this.val = val; this.left = null; this.right = null; this.bf = 0; this.height = 1; }
  function height(n) { return n ? n.height : 0; }
  function bf(n) { return n ? height(n.left) - height(n.right) : 0; }
  function update(n) {
    if (!n) return n;
    n.height = 1 + Math.max(height(n.left), height(n.right));
    n.bf = bf(n);
    return n;
  }
  function rotateRight(y) {
    var x = y.left; var T2 = x.right;
    x.right = y; y.left = T2;
    update(y); update(x);
    return x;
  }
  function rotateLeft(x) {
    var y = x.right; var T2 = y.left;
    y.left = x; x.right = T2;
    update(x); update(y);
    return y;
  }
  function insert(root, val) {
    if (!root) return new AVLNode(val);
    if (val < root.val) root.left = insert(root.left, val);
    else if (val > root.val) root.right = insert(root.right, val);
    else return root;
    update(root);
    var b = bf(root);
    if (b > 1 && val < root.left.val) return rotateRight(root);
    if (b < -1 && val > root.right.val) return rotateLeft(root);
    if (b > 1 && val > root.left.val) { root.left = rotateLeft(root.left); return rotateRight(root); }
    if (b < -1 && val < root.right.val) { root.right = rotateRight(root.right); return rotateLeft(root); }
    return root;
  }

  var insertSeq = [10,20,30,40,50,25];
  var steps = [];
  var tree = null;
  steps.push({ tree: null, action: '初始空树', inserted: null, rotation: null });
  for (var i = 0; i < insertSeq.length; i++) {
    var v = insertSeq[i];
    var before = tree;
    tree = insert(tree, v);
    var rot = null;
    if (before && tree) {
      if (before.val !== tree.val) rot = '旋转';
      else {
        var node = tree;
        while (node) {
          if (Math.abs(node.bf) >= 2) { rot = '旋转'; break; }
          if (v < node.val) node = node.left;
          else if (v > node.val) node = node.right;
          else break;
        }
      }
    }
    steps.push({ tree: cloneTree(tree), action: '插入 ' + v, inserted: v, rotation: rot });
  }
  steps.push({ tree: cloneTree(tree), action: '最终平衡树', inserted: null, rotation: null });
  steps.push({ tree: cloneTree(tree), action: '复位', inserted: null, rotation: null });

  function cloneTree(n) {
    if (!n) return null;
    var c = new AVLNode(n.val);
    c.left = cloneTree(n.left);
    c.right = cloneTree(n.right);
    c.height = n.height;
    c.bf = n.bf;
    return c;
  }

  (function verify(){
    var cases = [
      { step:0, desc:'空树' },
      { step:1, desc:'插入10' },
      { step:2, desc:'插入20' },
      { step:3, desc:'插入30,旋转' },
      { step:4, desc:'插入40' },
      { step:5, desc:'插入50,旋转' },
      { step:6, desc:'插入25' },
      { step:7, desc:'最终平衡' },
    ];
    cases.forEach(function(c){
      console.assert(steps[c.step], 'step ' + c.step + ' exists');
    });
    console.log('AVL steps verification passed');
  })();

  var svg = document.getElementById('stageSvg');
  var stepLabel = document.getElementById('stepLabel');
  var actionTag = document.getElementById('actionTag');
  var insertVal = document.getElementById('insertVal');
  var prevBtn = document.getElementById('prevBtn');
  var nextBtn = document.getElementById('nextBtn');

  var currentStep = 0;
  var totalSteps = steps.length - 1;

  function layoutTree(root, width, height) {
    if (!root) return [];
    var nodes = [];
    var edges = [];
    var xSpacing = width * 0.7;
    var ySpacing = 60;
    var startX = width / 2;
    var startY = 50;

    function traverse(node, x, y, level, offset) {
      if (!node) return;
      nodes.push({ val: node.val, bf: node.bf, x: x, y: y });
      var childY = y + ySpacing;
      var gap = xSpacing / Math.pow(2, level + 1);
      if (node.left) {
        var lx = x - gap;
        edges.push({ x1: x, y1: y + 18, x2: lx, y2: childY - 18 });
        traverse(node.left, lx, childY, level + 1, gap);
      }
      if (node.right) {
        var rx = x + gap;
        edges.push({ x1: x, y1: y + 18, x2: rx, y2: childY - 18 });
        traverse(node.right, rx, childY, level + 1, gap);
      }
    }
    traverse(root, startX, startY, 0, xSpacing);
    return { nodes: nodes, edges: edges };
  }

  function render(stepIdx) {
    var step = steps[Math.min(stepIdx, steps.length - 1)];
    var tree = step.tree;
    var w = 680, h = 360;
    var nodeR = 20;

    var html = '';
    if (!tree) {
      html = '<text x="' + (w/2) + '" y="' + (h/2) + '" text-anchor="middle" fill="' + text2 + '" font-size="16" class="node-text">空树</text>';
    } else {
      var layout = layoutTree(tree, w, h);
      for (var e = 0; e < layout.edges.length; e++) {
        var edge = layout.edges[e];
        html += '<line x1="' + edge.x1 + '" y1="' + edge.y1 + '" x2="' + edge.x2 + '" y2="' + edge.y2 + '" stroke="' + line + '" stroke-width="2"/>';
      }
      for (var n = 0; n < layout.nodes.length; n++) {
        var node = layout.nodes[n];
        var fill, strokeColor;
        if (node.bf === 0) { fill = bg2; strokeColor = accent; }
        else if (Math.abs(node.bf) >= 2) { fill = '#F87171'; strokeColor = '#B91C1C'; }
        else { fill = '#FBBF24'; strokeColor = '#D97706'; }
        html += '<circle cx="' + node.x + '" cy="' + node.y + '" r="' + nodeR + '" fill="' + fill + '" stroke="' + strokeColor + '" stroke-width="2"/>';
        html += '<text x="' + node.x + '" y="' + (node.y + 5) + '" text-anchor="middle" fill="' + ink + '" font-size="14" font-weight="600" class="node-text">' + node.val + '</text>';
        var bfLabel = node.bf >= 0 ? '+' + node.bf : '' + node.bf;
        var bfColor = node.bf === 0 ? text2 : (Math.abs(node.bf) >= 2 ? '#B91C1C' : '#D97706');
        html += '<text x="' + (node.x + 26) + '" y="' + (node.y - 10) + '" text-anchor="middle" fill="' + bfColor + '" font-size="11" font-family="ui-monospace, Consolas, monospace" font-variant-numeric="tabular-nums">BF=' + bfLabel + '</text>';
      }
    }

    svg.innerHTML = html;

    stepLabel.textContent = '步骤 ' + stepIdx + ' / ' + totalSteps;
    prevBtn.disabled = (stepIdx <= 0);
    nextBtn.disabled = (stepIdx >= totalSteps);

    var action = step.action || '';
    if (action.indexOf('旋转') !== -1 || step.rotation) {
      actionTag.className = 'action-tag';
      actionTag.textContent = '旋转';
    } else if (action.indexOf('插入') !== -1) {
      actionTag.className = 'action-tag';
      actionTag.textContent = '插入';
    } else {
      actionTag.className = 'action-tag none';
      actionTag.textContent = action;
    }
    insertVal.textContent = step.inserted ? '插入值: ' + step.inserted : '插入值: —';
  }

  function update() {
    render(currentStep);
  }

  prevBtn.addEventListener('click', function() {
    if (currentStep > 0) { currentStep--; update(); }
  });
  nextBtn.addEventListener('click', function() {
    if (currentStep < totalSteps) { currentStep++; update(); }
  });

  update();
})();
</script>
